  function zoomarea(a, b) {
    if (-9898 !== c.w1.x) {
      var f = b[0] < a[0] ? b[0] : a[0],
        g = b[1] < a[1] ? a[1] : b[1];
      f *= c.ratio;
      g *= c.ratio;
      c.w1.x = getvdcX(f, g);
      c.w1.y = getvdcY(f, g);
      f = b[0] < a[0] ? a[0] : b[0];
      a = b[1] < a[1] ? b[1] : a[1];
      f *= c.ratio;
      a *= c.ratio;
      c.w2.x = getvdcX(f, a);
      c.w2.y = getvdcY(f, a);
      redraw();
      sdiZoomFabric();
    }
  }
  function calc_extent() {
    var a = c.h * c.ratio,
      b = c.w * c.ratio;
    -9898 === c.w1.x &&
      ((c.w1.x = c.global_vdc_xs),
        (c.w1.y = c.global_vdc_ys),
        (c.w2.x = c.global_vdc_xe),
        (c.w2.y = c.global_vdc_ye),
        (c.zoomtype = 0));
    var f = c.w2.x - c.w1.x,
      g = c.w2.y - c.w1.y;
    c.h / g > c.w / f
      ? ((c.vdcppx = f / c.w), (c.vdcppy = c.vdcppx))
      : ((c.vdcppy = g / c.h), (c.vdcppx = c.vdcppy));
    f = get_version();
    UTF8ToString(f);
    sdi_set_picture(1);
    set_screen_dimensions(b, a);
    c.firstTimeFileLoad = !1;
    wasm_set_viewport(c.w1.x, c.w1.y, c.w2.x, c.w2.y);
    set_fit_transform(1e4, 1e4);
    c.firstTimeFileLoad = !1;
  }

  class contextData {
    constructor() {
      this.id;
      this.label = [];
      this.ref = [];
      this.count;
    }
  };

  var loadfile;
  var extended_link = false;
  function parseCalloutsGM() {
    extended_link = "false";
    var callouts = document.getElementsByTagName("gm:callout");
    for (callout of callouts) {

      var final;
      var id = callout.getAttribute("id");
      var callout_texts = callout.getElementsByTagName("gm:callout-text");
      for (callout_text of callout_texts) {
        var divs = callout_text.getElementsByTagName("DIV");
        for (div of divs) {
          var tooltip = div.innerHTML;
          var tooltip = tooltip.replaceAll('&amp;', '&')
          tooltip = tooltip.replaceAll('&AMP;', '&');
          tooltip = tooltip.replaceAll('&nbsp;', ' ');
          tooltip = tooltip.replaceAll('&ensp;', '  ');
          tooltip = tooltip.replaceAll('&emsp;', '    ');
          tooltip = tooltip.replaceAll('&lt;', '<')
          tooltip = tooltip.replaceAll('&gt;', '>')
          tooltip = tooltip.replaceAll('&quot;', '"');
          tooltip = tooltip.replaceAll('&#039;', '\'');

          xmlids.push(id);
          xmltooltips.push(tooltip);
        }
      }
      // end callout_text and divs
      extended_link = "false";
      var extlink = callout.getElementsByTagName("gm:extended-link");
      if (extlink.length != 0) extended_link = extlink[0].getAttribute("inline");
      if (extended_link === "true") {
        var a = new contextData;
        a.id = id;

        var locators = extlink[0].getElementsByTagName("gm:locator");
        var count = 0;
        for (locator of locators) {
          href = locator.getAttribute("href");

          var start;
          var end;

          if (href) a.ref.push(href);
          var title = locator.getAttribute("title");
          // replace HTML special characters

          title = title.replaceAll('&amp;', '&');
          title = title.replaceAll('&nbsp;', ' ');
          title = title.replaceAll('&ensp;', '  ');
          title = title.replaceAll('&emsp;', '    ');
          title = title.replaceAll('&lt;', '<');
          title = title.replaceAll('&gt;', '>');
          title = title.replaceAll('&quot;', '"');
          title = title.replaceAll('&#039;', '\'');

          a.label.push(title);
          var link = locator.getAttribute("xml:link");
          let behavior = locator.getAttribute("behavior");

          if (behavior) {
            start = behavior.indexOf("id");
            end = behavior.indexOf(",", start);
            final = behavior.substring(start + 3, end);
          }
          count++;

        } //end locator
        a.count = count;
        citem.push(a);
      } // end isit
    } //end callouts

  }
  function parseCallouts() {
    extended_link = "false";
    var callouts = document.getElementsByTagName("hotspot");
    for (callout of callouts) {

      var final;
      var id = callout.getAttribute("applicationStructureIdent");
      var tooltip = callout.getAttribute("hotspotTitle");
      href = callout.getAttribute("href");
      xmlids.push(id);
      var tooltip = tooltip.replaceAll('&amp;', '&')

      tooltip = tooltip.replaceAll('&AMP;', '&');
      tooltip = tooltip.replaceAll('&nbsp;', ' ');
      tooltip = tooltip.replaceAll('&ensp;', '  ');
      tooltip = tooltip.replaceAll('&emsp;', '    ');
      tooltip = tooltip.replaceAll('&lt;', '<')
      tooltip = tooltip.replaceAll('&gt;', '>')
      tooltip = tooltip.replaceAll('&quot;', '"');
      tooltip = tooltip.replaceAll('&#039;', '\'');
      xmltooltips.push(tooltip);

      var a = new contextData;
      a.id = id;
      a.count = 1;
      a.label.push("popover");
      a.ref.push(href);
      citem.push(a);

    } //end callouts

  }
