  const normalizePosition = (mouseX, mouseY) => {
    const scope = document.querySelector("body");
    var csx = c.fcanvas._offset.left - $(window).scrollLeft();
    var csy = c.fcanvas._offset.top - $(window).scrollTop();
    var we = window.innerWidth - 25;
    var he = window.innerHeight - 30;
    //console.log(" window size " + we + "," + he);
    const {
      left: scopeOffsetX,
      top: scopeOffsetY,
    } = scope.getBoundingClientRect();
    //console.log(" scope offset x and y " + scopeOffsetX + "," + scopeOffsetY);
    const scopeX = mouseX - scopeOffsetX;
    const scopeY = mouseY - scopeOffsetY;
    const h = contextMenu.clientHeight;
    const w = contextMenu.clientWidth;
    //console.log("Box size " + w + "," + h);
    //console.log(" scopex and y " + scope.clientWidth + "," + scope.clientHeight);

    var outOfBoundsOnX =
      scopeX + w > we;
    //   if (w > scope.clientWidth  )outOfBoundsOnX=false;
    const outOfBoundsOnY =
      scopeY + h > he;

    let normalizedX = mouseX;
    let normalizedY = mouseY;
    if (outOfBoundsOnX) {

      normalizedX = we - w;
    }
    if (outOfBoundsOnY)
      normalizedY = he - h;

    return { normalizedX, normalizedY };
  }

  $(document.getElementById(thisClass.id)).contextmenu(function (event) {
    event.preventDefault();
    if (c.magnify == 1) {
      c.zoomC.style.display = "none";
      setDefaultCursor();
      c.magnify = 0;
    }
    c.fcanvas.selection = false;
    c.ctxx.clearRect(0, 0, c.canvas2.width * 10, c.canvas2.height * 10);
    var currentScrollx = $(window).scrollLeft();
    var currentScrolly = $(window).scrollTop();
    if (c.ctxx.isPointInPath(c.xdown, c.ydown)) {
      if (hscursor.includes("onehand")) {
        contextMenu.style.display = "none";
        var cid = "hs_context" + thisClass.id;
        contextMenu = document.getElementById(cid);
        var a = contextMenu.lastElementChild;
        var b = a.innerHTML;
        var start = b.indexOf("href");
        var end = b.indexOf(">", start);
        var final = b.substring(start + 6, end - 1);
        cid = "sdihotspot=" + a.id;
        document.cookie = cid;
        setTimeout(final, 1);
      }
      else if (hscursor.includes("multihand")) {
        contextMenuOn = 1;
        contextMenu.style.display = "block"; // turn on the context menu, #items > 1
        contextMenu.style.padding = "1px 12px 1px 12px";
        // var mx =  c.xdown   ;
        // var my =  c.ydown - currentScroll + 80; 
        var mx = c.xdown + c.fcanvas._offset.left - currentScrollx;
        var my = c.ydown + c.fcanvas._offset.top - currentScrolly;
        //  contextMenu.style.top = `${my}px` ;
        //   contextMenu.style.left = `${mx}px`;
        // contextMenu.classList.add('visible');
        contextMenu.style.zIndex = 10000;
        contextMenu.style.position = 'fixed';
        contextMenu.style.whiteSpace = 'nowrap';

        contextMenu.style.width = "auto";
        contextMenu.style.borderRadius = "5px";
        contextMenu.style.borderthickness = 3;
        contextMenu.style.strokeColor = "#FF0000";
        contextMenu.style.background = "#EEEEEE";
        var { normalizedX, normalizedY } = normalizePosition(mx, my);
        contextMenu.style.top = `${normalizedY}px`;
        contextMenu.style.left = `${normalizedX}px`;
      }
    }
  }); // end fire context menu

  function contextMenuadd(contextMenu, menustring, icount, id, href, screentip) {
    maxh = 0;
    c.ctx.font = "12px Arial";
    action = function (e) {
      let currentRow = $(e.target)[0].parentElement;
      var cid = "sdihotspot=" + currentRow.id;
      document.cookie = cid;
      contextMenuOn = 0;
    };

    var tooltip = screentip;
    var value = 0;
    var w = 0;
    while (value != -1) {
      value = screentip.indexOf("<br>");
      var single = screentip.substring(1, value);

      screentip = screentip.substring(value + 4);

      w = c.ctx.measureText(single).width;
      var h = c.ctx.measureText("O").width;

      maxh += h;
      if (maxw < w) maxw = w;

    }
    screentip = tooltip;
    if (icount == 0) {
      screentip += "<br>";
      var menuitem = document.createElement('LI');
      menuitem.classList.add("hotspot__item");
      menuitem.innerHTML = '<a style="font-family:Arial;font-size:12px;padding-left:10px;padding-bottom:15px;color:#777777;text-decoration:underline;">' + screentip + '</a>';
      contextMenu.appendChild(menuitem);
    }
    var menuitem = document.createElement('LI');
    menuitem.addEventListener('click', action);
    menuitem.classList.add("hotspot__item");
    menuitem.addEventListener('mouseover', function handleMouseOver(e) {
      e.target.style.color = 'blue';
    });
    menuitem.addEventListener('mouseout', function handleMouseOver(e) {
      e.target.style.color = 'black';
    });

    menuitem.innerHTML = '<a style="font-family:Arial;font-size:12px;padding-left:10px;hover:#ff00ff;color:#000000;text-decoration:none; " href=' + href + '>' + menustring + '</a>';
    menuitem.row = icount;
    menuitem.id = id;
    contextMenu.appendChild(menuitem);
  };

