  var flipped = false;
  function mirror() {
    document.querySelector("#" + thisClass.id + "myrot").style.transform = flipped ? 'scaleX(1)' : 'scaleX(-1)';
    flipped = !flipped;
  }

  function scaleImageData(imageData, scale) {
    const main = document.getElementById(thisClass.id + "canvas1");
    const ctx1 = main.getContext('2d');
    var scaled = ctx1.createImageData(imageData.width * scale, imageData.height * scale);
    var subLine = ctx1.createImageData(scale, 1).data
    for (var row = 0; row < imageData.height; row++) {
      for (var col = 0; col < imageData.width; col++) {
        var sourcePixel = imageData.data.subarray(
          (row * imageData.width + col) * 4,
          (row * imageData.width + col) * 4 + 4
        );
        for (var x = 0; x < scale; x++) subLine.set(sourcePixel, x * 4)
        for (var y = 0; y < scale; y++) {
          var destRow = row * scale + y;
          var destCol = col * scale;
          scaled.data.set(subLine, (destRow * scaled.width + destCol) * 4)
        }
      }
    }
    return scaled;
  }

