  function chk() {
    setDefaultCursor();
    c.cancel = 1;
    c.zoomarea = 0;
    if (c.magnify == 1) {
      c.zoomC.style.display = "none";
      c.magnify = 0;
    }
    setdragmode.mode = -1;
    c.fcanvas.selection = false;
    startSelection();
  }

  function chkey(e) {
    switch (e.which) {
      case 43:     //+
      case 187:   // += key
      case 107:
        setzoomin();
        break;
      case 45:    //-
      case 189:   // _- key
      case 109:    //-
        setzoomout();
        break;
      case 96:
      case 48:       //0
      case 78:      //N
      case 110:   //n
        setHyperlink();
        break;
      case 97:
      case 49:
        magnify();       //1
        break;
      case 98:
      case 50:      //2
        setzoom();
        break;
      case 99:
      case 51:       //3
      case 80:       //P
      case 112:      //p
        setpanmode();
        break;

      case 100:
      case 52:     //4
      case 36:
        setfit();
        break;       //home
    }

    if (e.which == 27) { //escape
      setDefaultCursor();
      c.cancel = 1;
      c.zoomarea = 0;
      if (c.magnify == 1) {
        c.zoomC.style.display = "none";
        c.magnify = 0;
        setDefaultCursor();
      }
      setdragmode.mode = -1;
      c.fcanvas.selection = false;
      startSelection();
      setDefaultCursor();
    }
  }

  function setDefaultCursor() {
    $('*').css('cursor', '');
  }
  function setCursor(a) {
    $('*').css('cursor', a);
  }

  /* ============================================================================
  startDrawing       Draw an object redlining
  ============================================================================ */

  function startDrawing(type) {

    c.drawmode = true;
    setSelectionMode(false);
    c.fcanvas.isDrawingMode = false;
    drawtext = false;
    d.isDrawing = true;
    switch (type) {
      case "Text":
        drawtext = true;
        c.fcanvas.defaultCursor = 'text';
        break;
      case "Text2":
        c.fcanvas.defaultCursor = 'text';
        break;
      case "FreeFormLine":
        c.fcanvas.freeDrawingBrush.width = d.strokeWidth;
        var rgb = hexToRgb(d.strokeColor);
        c.fcanvas.freeDrawingBrush.color = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + d.opacity + ')';
        c.fcanvas.isDrawingMode = true;
        break;
      default:
        c.fcanvas.defaultCursor = 'crosshair';
    }
    c.fcanvas.selection = false;
    d.drawingMode = type;
  }

  function deleteObject() {
    var activeObject = c.fcanvas.getActiveObjects();
    if (activeObject == null || activeObject.length == 0)
      return;
    // hideTextBox();
    d.state = JSON.stringify(c.fcanvas);
    c.fcanvas.discardActiveObject();

    activeObject.forEach(function (object) {
      c.fcanvas.remove(object);
    });
    d.state2 = JSON.stringify(c.fcanvas);
  }

  function undo_delete_Object() {
    state3 = JSON.stringify(c.fcanvas);
    if (d.state != null && d.state2 === state3) {
      c.fcanvas.loadFromJSON(d.state, function () {
      });
    }
    d.state = null;

    c.fcanvas.renderAll();
    startSelection();
  }

