  function openTif(f) {

    //const isDefined = typeof Tiff !== 'undefined';
    var tiff = new Tiff({ buffer: f });

    var canvas = tiff.toDataURL();
    var width = tiff.width();
    var height = tiff.height();
    if (canvas) {

      try {
        c.fcanvas.forEachObject(function (object) {
          var type = object.get('type');
          if (type == "sdiTif") {
            c.fcanvas.remove(object);
            throw e;
          }
        });
      } catch (e) {

      }

    }
    setfit(0);
    fabric.Image.fromURL(canvas, function (img) {
      img.set({
        left: 0,
        top: 0,
        originX: 'left',
        originY: 'top',
        type: 'sdiTif',
        //      ZIndex: -1,
        lockMovementX: true,
        lockMovementY: true,

        transparentCorners: false,
        selectable: false,
        evented: false
      });

      if (width > c.fcanvas.getWidth()) var q = c.fcanvas.getWidth();
      var h = c.fcanvas.getHeight();
      q >= h ? img.scaleToWidth(q) : img.scaleToHeight(h);
      c.fcanvas.add(img);
      // c.fcanvas.sendToBack(img);
      // c.fcanvas.centerObject(img);
    });

    //c.fcanvas.renderAll();
    openCGMfile('images/blank.cgm');

  }


