  this.highlightID = function (str, color) {
    if (str.length == 0) return;
    if (str == "null") return;
    if (str === 0) hotspot(0);

    var strascii = [];
    for (i = 0; i < str.length; i++) strascii.push(str[i].charCodeAt(0));
    const tarr = new Uint32Array(strascii.length)
    for (i = 0; i < strascii.length; i++) {
      tarr[i] = strascii[i];
    }
    var strbuf = Module._malloc(tarr.length * tarr.BYTES_PER_ELEMENT);
    Module.HEAP32.set(tarr, strbuf >> 2);

    var xy = getXY(strbuf, str.length);
    var b = c.fcanvas.width / 2;
    var f = c.fcanvas.height / 2;
    var a = b - xy[0] / 10;
    var g = f - xy[1] / 10;
    c.dragged = !0;
    c.fcanvas.relativePan(new fabric.Point(a, g));
    (c.zoomtype = 2),
        (c.w2.x -= c.vdcppx * a),
        (c.w2.y += c.vdcppy * g),
        (c.w1.x -= c.vdcppx * a),
        (c.w1.y += c.vdcppy * g),
        redraw();
    hl_hotspot(strbuf, str.length, color);
  };

