function cgmparse(id, flag, rootfolder) {
  var scripts = []
  scripts.push(rootfolder + 'jquery-3.5.1.min.js');
  scripts.push(rootfolder + 'jquery-ui.min.js');
  scripts.push(rootfolder + 'pako.js');
  scripts.push(rootfolder + 'tiff.min.js');
  scripts.push(rootfolder + 'popper.min.js');
  //scripts.push(rootfolder + 'js/bootstrap.min.js');
  scripts.push(rootfolder + 'fabric.js');

  var styles = [];

  //styles.push(rootfolder + "css/bootstrap.css");
  styles.push(rootfolder + "css/viewButton.css");
  styles.push(rootfolder + "css/sdi_icons.css");
  /* push more styles as needed */

  loadScript(0);

  function loadCSS(index) {
    var css = document.createElement('link');
    css.setAttribute('rel', "stylesheet");
    css.setAttribute('type', 'text/css');
    css.setAttribute('href', styles[index]);

    var loadFunction = function () {
      if (index < styles.length - 1) {
        loadCSS(index + 1); //load next css on success
      }
      else if (index == styles.length - 1) {
        CreateCgmViews(id, flag); //Safe to reate CGM View now
      }
    };

    css.onload = loadFunction;
    css.onreadystatechange = loadFunction;
    document.getElementsByTagName("head")[0].appendChild(css);
  }

  function loadScript(index) {
    var script = document.createElement('script');
    script.setAttribute('src', scripts[index]);
    script.setAttribute('type', 'text/javascript');
    script.setAttribute('defer', true);

    var loadFunction = function () {
      if (index < scripts.length - 1) {
        loadScript(index + 1); //load next script on success
      }
      else if (index == scripts.length - 1) {
        loadCSS(0); //Scripts are done. Lets load CSS
      }
    };

    script.onload = loadFunction;
    script.onreadystatechange = loadFunction;
    document.getElementsByTagName("head")[0].appendChild(script);
  }
}
